import argparse

class RomanConverter:
    @staticmethod
    def to_roman(num):
        if not (0 < num < 4000):
            raise ValueError("Number out of range (must be 1..3999)")
        val = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1]
        syms = ["M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"]
        roman_num = ''
        i = 0
        while num > 0:
            for _ in range(num // val[i]):
                roman_num += syms[i]
                num -= val[i]
            i += 1
        return roman_num

    @staticmethod
    def from_roman(s):
        roman_map = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}
        num = 0
        prev_value = 0
        s = s.upper()
        for char in reversed(s):
            value = roman_map.get(char, 0)
            if value < prev_value:
                num -= value
            else:
                num += value
            prev_value = value
        # Validate that the conversion back to roman matches input (to catch invalid numerals)
        if RomanConverter.to_roman(num) != s:
            raise ValueError(f"Invalid Roman numeral: {s}")
        return num


def main():
    parser = argparse.ArgumentParser(description="Convert integers to Roman numerals and vice versa.")
    group = parser.add_mutually_exclusive_group(required=True)
    group.add_argument("-i", "--integer", type=int, help="Convert integer to Roman numeral")
    group.add_argument("-r", "--roman", type=str, help="Convert Roman numeral to integer")

    args = parser.parse_args()

    if args.integer is not None:
        print(RomanConverter.to_roman(args.integer))
    elif args.roman is not None:
        print(RomanConverter.from_roman(args.roman))

if __name__ == "__main__":
    main()
